const recipes = $("FormatItems For ImageAssistant")
  .all()
  .map((item) => item.json);

const imageData = $input.all().map((item) => item.json);

const updatedRecipes = recipes.map((recipe) => {
  const img = imageData.find((img) => img.id === recipe.id);
  if (img) {
    recipe.image_url = img.image_url;
  }

  // Generate YouTube Search Query from title
  const title = recipe.title.trim();
  let searchQuery = "";

  if (title.toLowerCase().includes(" and ")) {
    const parts = title.split(/ and /i);
    const before = parts[0].trim().split(" ");
    const after = parts[1].trim().split(" ");
    const lastTwoBefore = before.slice(-2);
    const firstTwoAfter = after.slice(0, 2);
    searchQuery = [...lastTwoBefore, ...firstTwoAfter].join(" ");
  } else {
    searchQuery = title;
  }

  recipe.query = searchQuery;

  // Rename image_url → url for downstream compatibility
  recipe.url = recipe.image_url;
  delete recipe.image_url;

  return recipe;
});

return updatedRecipes;

