const now = new Date();
const timeZone = 'America/New_York'; // Define once to avoid repetition

// Extract the current hour (in 24-hour format) in EST for meal time classification
const estHour = parseInt(now.toLocaleString('en-US', {
  timeZone,
  hour: '2-digit',
  hour12: false
}), 10);

// Get day name in EST to determine if it's a weekday or weekend
const dayName = now.toLocaleString('en-US', {
  timeZone,
  weekday: 'long'
});

const isWeekend = (dayName === 'Saturday' || dayName === 'Sunday');
const result = isWeekend ? 'Weekend' : 'Weekday';

// Format current time in EST (e.g., "10:27 PM") for UI display
const estFormattedTime = now.toLocaleTimeString('en-US', {
  timeZone,
  hour: '2-digit',
  minute: '2-digit',
  hour12: true
});

// Classify meal type based on the current EST hour
let mealType = '';
if (estHour >= 5 && estHour < 11) {
  mealType = 'Breakfast';
} else if (estHour >= 11 && estHour < 16) {
  mealType = 'Lunch';
} else if (estHour >= 16 && estHour < 24) {
  mealType = 'Dinner';
} else {
  mealType = 'Snack';
} 
mealType = 'Dinner'; //testing purpose only
// Output values for use in n8n or UI
return [
  {
    json: {
      mealType: mealType,
      formattedTime: estFormattedTime,
      result: result,  // "Weekday" or "Weekend"
    }
  }
];

const rawJson = $input.first().json.output;

// Step 1: Clean the triple-backtick wrapper and parse the JSON string
const cleaned = rawJson.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);

// Step 2: Transform each recipe to match expected output format
const transformedRecipes = parsed.recipes.map((recipe) => {
  // console.log(recipe['ingredients used']);
  return {
    id: parseInt(recipe.id),
    title: recipe.title,
    steps: recipe.steps.join('\n'), // join array to single string
    time: recipe.time.replace('Prep Time is ', 'Prep Time: ').replace('Cook Time is ', 'Cook Time: '),
    nutrition: Object.entries(recipe.nutrition).map(([key, value]) => `${key}: ${value}`), // object to array of strings
    //ingredients: Array.isArray(recipe['ingredients used']) ? recipe['ingredients used'] : []
    ingredients: Array.isArray(recipe['ingredients']) 
  ? recipe['ingredients'] 
  : (Array.isArray(recipe['ingredients used']) ? recipe['ingredients used'] : []),
   fun_fact: recipe.fun_fact
  };
});

// Step 3: Return formatted output
return [
  {
    json: {
      output: {
        recipes: transformedRecipes
      }
    }
  }
];

